	@Test
	void cancellationBeforeRemoteQueryRegistrationStillCancelsTheLaterQuery() throws Exception {
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		ExecutorService serverThreads = Executors.newVirtualThreadPerTaskExecutor();
		server.setExecutor(serverThreads);
		CountDownLatch queryArrived = new CountDownLatch(1);
		CountDownLatch allowRegistration = new CountDownLatch(1);
		CountDownLatch firstNotFound = new CountDownLatch(1);
		CountDownLatch remoteCancelled = new CountDownLatch(1);
		AtomicBoolean registered = new AtomicBoolean();
		server.createContext("/protocol", exchange -> {
			byte[] version = "12".getBytes(StandardCharsets.UTF_8);
			exchange.sendResponseHeaders(200, version.length);
			try (exchange) {
				exchange.getResponseBody().write(version);
			}
		});
		server.createContext("/repositories/memory", exchange -> {
			try (exchange) {
				String query = exchange.getRequestURI().getRawQuery();
				if (query != null && query.contains("cancel-query=true")) {
					if (registered.get()) {
						remoteCancelled.countDown();
						exchange.sendResponseHeaders(204, -1);
					} else {
						firstNotFound.countDown();
						exchange.sendResponseHeaders(404, -1);
					}
				} else {
					exchange.getRequestBody().readAllBytes();
					queryArrived.countDown();
					awaitIgnoringInterrupts(allowRegistration);
					registered.set(true);
					awaitIgnoringInterrupts(remoteCancelled);
					exchange.sendResponseHeaders(204, -1);
				}
			} catch (IOException ignored) {
				// The client may close its HTTP connection after cancellation.
			}
		});
		server.start();
		HTTPRepository remote = new HTTPRepository("http://127.0.0.1:" + server.getAddress().getPort(), "memory");
		remote.init();
		try {
			replaceServlet(remote, mock(RepositoryManager.class), 30_000);
			Future<?> task = threads
					.submit(() -> service(countRequest("late-registration"), new MockHttpServletResponse()));
			assertThat(queryArrived.await(10, TimeUnit.SECONDS)).isTrue();
			MockHttpServletRequest cancel = new MockHttpServletRequest("POST", "/explore");
			cancel.addParameter("action", "cancel-query");
			cancel.addParameter("query-request-id", "late-registration");
			MockHttpServletResponse cancellation = new MockHttpServletResponse();
			servlet.service(cancel, cancellation);
			assertThat(firstNotFound.await(10, TimeUnit.SECONDS)).isTrue();
			assertThat(cancellation.getStatus()).isEqualTo(204);
			// The retry must retain ownership after the Workbench response has finished.
			task.get(10, TimeUnit.SECONDS);
			allowRegistration.countDown();
			assertThat(remoteCancelled.await(10, TimeUnit.SECONDS)).isTrue();
		} finally {
			allowRegistration.countDown();
			remoteCancelled.countDown();
			servlet.destroy();
			servlet = new ExploreServlet(30_000);
			remote.shutDown();
			server.stop(0);
			serverThreads.shutdownNow();
		}
	}

