	void abandonedPageAcquisitionsKeepTheirAdmissionPermitsUntilTheyReturn() throws Exception {
		assertAbandonedAcquisitionsKeepPermits(false);
	}

	@Test
	void abandonedCountAcquisitionsKeepTheirAdmissionPermitsUntilTheyReturn() throws Exception {
		assertAbandonedAcquisitionsKeepPermits(true);
	}

	private void assertAbandonedAcquisitionsKeepPermits(boolean count) throws Exception {
		int maximum = count ? BrowseList.MAX_IN_FLIGHT_COUNTS : BrowseList.MAX_IN_FLIGHT_PAGE_OPERATIONS;
		CountDownLatch entered = new CountDownLatch(maximum);
		CountDownLatch closed = new CountDownLatch(maximum);
		AtomicInteger acquisitions = new AtomicInteger();
		AtomicInteger prepared = new AtomicInteger();
		Repository blocking = new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() {
				acquisitions.incrementAndGet();
				entered.countDown();
				awaitIgnoringInterrupts(releaseAcquisition);
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public TupleQuery prepareTupleQuery(QueryLanguage language, String text, String base) {
						prepared.incrementAndGet();
						return super.prepareTupleQuery(language, text, base);
					}

					@Override
					public void close() {
						super.close();
						closed.countDown();
					}
				};
			}
		};
		replaceServlet(blocking, mock(RepositoryManager.class), 3_000);
		List<Future<?>> running = new ArrayList<>();
		for (int i = 0; i < maximum; i++) {
			String id = "blocked-" + i;
			running.add(threads.submit(() -> service(count ? countRequest(id) : request("rows"),
					new MockHttpServletResponse())));
		}
		assertThat(entered.await(10, TimeUnit.SECONDS)).isTrue();
		for (Future<?> task : running) {
			task.get(10, TimeUnit.SECONDS);
		}
		assertThat(acquisitions).hasValue(maximum);
		MockHttpServletResponse queued = new MockHttpServletResponse();
		Future<?> extra = threads.submit(() -> service(count ? countRequest("queued") : request("rows"), queued));
		extra.get(10, TimeUnit.SECONDS);
		assertThat(records(queued).getLast().path("status").asInt()).isEqualTo(504);
		assertThat(acquisitions).hasValue(maximum);
		releaseAcquisition.countDown();
		assertThat(closed.await(10, TimeUnit.SECONDS)).isTrue();
		assertThat(prepared).hasValue(0);
	}

